<template>
  <div><div class="catalog-heading"><div><p class="eyebrow">商品运营</p><h1>分类管理</h1><p class="muted">最多两级分类，商品归属二级分类。</p></div><button class="primary-button" @click="create(null)">＋ 新增一级分类</button></div>
    <p v-if="message" class="form-message-success" role="status">{{ message }}</p><p v-if="actionError" class="form-message-error" role="alert">{{ actionError }}</p>
    <PageStatus :loading="loading" :error="error" :empty="!tree.length" empty-text="还没有分类，先创建一级分类。" @retry="load" />
    <div v-if="editing" class="category-editor"><form @submit.prevent="save"><div class="catalog-heading"><h2>{{ editingId === null ? '新增分类' : '编辑分类' }}</h2><button type="button" class="text-action" @click="editing = false">关闭</button></div><div class="address-fields"><label class="form-field">分类名称<input v-model.trim="form.name" required maxlength="50"></label><label class="form-field">父级分类<select v-model="form.parentId"><option :value="null">无（一级分类）</option><option v-for="root in tree.filter(c => c.id !== editingId)" :key="root.id" :value="root.id">{{ root.name }}</option></select></label><label class="form-field">排序值<input v-model.number="form.sortOrder" type="number" min="0" max="2147483647" step="1" required><small class="field-hint">数值越小，展示越靠前</small></label><label class="form-field">状态<select v-model.number="form.status"><option :value="1">启用</option><option :value="0">停用</option></select></label></div><div class="form-actions"><button class="primary-button" :disabled="busy">{{ busy ? '保存中…' : '保存分类' }}</button><button type="button" class="secondary-button" @click="editing = false">取消</button></div></form></div>
    <div class="category-tree"><article v-for="root in tree" :key="root.id" class="category-tree-group"><div class="category-tree-row category-root-row"><div><strong>{{ root.name }}</strong><span class="status-pill" :class="{ 'status-off': !root.status }">{{ root.status ? '启用' : '停用' }}</span><small class="muted">排序 {{ root.sortOrder }}</small></div><div class="table-actions"><button class="text-action" @click="create(root.id)">＋ 二级分类</button><button class="text-action" @click="edit(root)">编辑</button><button class="text-action" :disabled="busy" @click="toggle(root)">{{ root.status ? '停用' : '启用' }}</button><button class="text-action danger-text" :disabled="busy" @click="remove(root)">删除</button></div></div><div v-for="child in root.children" :key="child.id" class="category-tree-row category-child-row"><div><span class="tree-branch">└</span>{{ child.name }}<span class="status-pill" :class="{ 'status-off': !child.status || !root.status }">{{ !root.status ? '父级停用' : child.status ? '启用' : '停用' }}</span><small class="muted">排序 {{ child.sortOrder }}</small></div><div class="table-actions"><button class="text-action" @click="edit(child)">编辑</button><button class="text-action" :disabled="busy" @click="toggle(child)">{{ child.status ? '停用' : '启用' }}</button><button class="text-action danger-text" :disabled="busy" @click="remove(child)">删除</button></div></div><p v-if="!root.children.length" class="category-empty-note">暂无二级分类</p></article></div>
  </div>
</template>
<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { ElMessageBox } from 'element-plus'
import 'element-plus/es/components/message-box/style/css'
import PageStatus from '../components/PageStatus.vue'
import { adminCategories, saveCategory, deleteCategory, type CategoryPayload } from '../api/admin-catalog'
import { errorMessage, type Category } from '../api/catalog'
const tree = ref<Category[]>([]), loading = ref(false), error = ref(''), actionError = ref(''), message = ref(''), editing = ref(false), editingId = ref<number | null>(null), busy = ref(false)
const form = reactive<CategoryPayload>({ name: '', parentId: null, status: 1, sortOrder: 0 })
async function load() { loading.value = true; error.value = ''; try { tree.value = await adminCategories() } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } }
function create(parentId: number | null) { editing.value = true; editingId.value = null; Object.assign(form, { name: '', parentId, status: 1, sortOrder: 0 }); actionError.value = ''; message.value = '' }
function edit(item: Category) { editing.value = true; editingId.value = item.id; Object.assign(form, { name: item.name, parentId: item.parentId, status: item.status, sortOrder: item.sortOrder }); actionError.value = ''; message.value = '' }
async function save() { busy.value = true; actionError.value = ''; try { await saveCategory(editingId.value, { ...form }); editing.value = false; message.value = '分类已保存'; await load() } catch (e) { actionError.value = errorMessage(e) } finally { busy.value = false } }
async function toggle(item: Category) { if (item.status) { try { await ElMessageBox.confirm('停用后，该分类及其下商品将暂时不在商城展示。', '停用分类', { confirmButtonText: '停用', cancelButtonText: '取消' }) } catch { return } } busy.value = true; actionError.value = ''; try { await saveCategory(item.id, { name: item.name, parentId: item.parentId, sortOrder: item.sortOrder, status: item.status ? 0 : 1 }); await load() } catch (e) { actionError.value = errorMessage(e) } finally { busy.value = false } }
async function remove(item: Category) { try { await ElMessageBox.confirm('确认删除分类“' + item.name + '”？存在子分类或关联商品时无法删除。', '删除分类', { confirmButtonText: '删除', cancelButtonText: '取消', type: 'warning' }) } catch { return } busy.value = true; actionError.value = ''; try { await deleteCategory(item.id); await load() } catch (e) { actionError.value = errorMessage(e) } finally { busy.value = false } }
onMounted(load)
</script>
